import csv
from collections import defaultdict
import statistics
import json

rows = []
with open('/app/benchmark/data.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        rows.append(row)

# Waiting time by location_type and time_slot
print("=== WAITING TIME HEATMAP: Location x Time Slot ===")
wt_heatmap = defaultdict(lambda: defaultdict(list))
for r in rows:
    wt_heatmap[r['location_type']][r['time_slot']].append(float(r['waiting_time']))

for loc in ['Urban', 'Highway', 'Suburban']:
    for slot in ['Off-Peak', 'Mid-Peak', 'Peak']:
        vals = wt_heatmap[loc][slot]
        if vals:
            print(f"{loc}/{slot}: avg={statistics.mean(vals):.2f}, count={len(vals)}")

# Queue length by location_type and time_slot
print("\n=== QUEUE LENGTH HEATMAP: Location x Time Slot ===")
for loc in ['Urban', 'Highway', 'Suburban']:
    for slot in ['Off-Peak', 'Mid-Peak', 'Peak']:
        vals = [float(r['queue_length']) for r in rows if r['location_type']==loc and r['time_slot']==slot]
        if vals:
            print(f"{loc}/{slot}: avg={statistics.mean(vals):.2f}")

# Station load by location_type and time_slot
print("\n=== STATION LOAD HEATMAP: Location x Time Slot ===")
for loc in ['Urban', 'Highway', 'Suburban']:
    for slot in ['Off-Peak', 'Mid-Peak', 'Peak']:
        vals = [float(r['station_load']) for r in rows if r['location_type']==loc and r['time_slot']==slot]
        if vals:
            print(f"{loc}/{slot}: avg={statistics.mean(vals):.2f}")

# Renewable ratio by weather and time slot
print("\n=== RENEWABLE RATIO: Weather x Time Slot ===")
for weather in ['Clear', 'Cloudy', 'Rainy', 'Snowy']:
    for slot in ['Off-Peak', 'Mid-Peak', 'Peak']:
        vals = [float(r['renewable_energy_ratio']) for r in rows if r['weather_condition']==weather and r['time_slot']==slot]
        if vals:
            print(f"{weather}/{slot}: avg={statistics.mean(vals)*100:.1f}%")

# Traffic density analysis
print("\n=== WAITING TIME BY TRAFFIC DENSITY ===")
for td in ['Low', 'Medium', 'High']:
    vals = [float(r['waiting_time']) for r in rows if r['traffic_density']==td]
    if vals:
        print(f"{td}: avg_wait={statistics.mean(vals):.2f}, count={len(vals)}")

# Charging priority distribution
print("\n=== CHARGING PRIORITY DISTRIBUTION ===")
priority_counts = defaultdict(int)
for r in rows:
    priority_counts[r['charging_priority']] += 1
for p, c in sorted(priority_counts.items()):
    print(f"{p}: {c} ({c/len(rows)*100:.1f}%)")

# Electricity price by time slot
print("\n=== ELECTRICITY PRICE BY TIME SLOT ===")
for slot in ['Off-Peak', 'Mid-Peak', 'Peak']:
    vals = [float(r['electricity_price']) for r in rows if r['time_slot']==slot]
    if vals:
        print(f"{slot}: avg_price={statistics.mean(vals):.2f}")

# Renewable ratio by location_type and weather
print("\n=== RENEWABLE RATIO: Location x Weather ===")
for loc in ['Urban', 'Highway', 'Suburban']:
    for weather in ['Clear', 'Cloudy', 'Rainy']:
        vals = [float(r['renewable_energy_ratio']) for r in rows if r['location_type']==loc and r['weather_condition']==weather]
        if vals:
            print(f"{loc}/{weather}: avg={statistics.mean(vals)*100:.1f}%")

# SOC analysis
print("\n=== SOC ANALYSIS ===")
initial_socs = [float(r['initial_soc']) for r in rows]
final_socs = [float(r['final_soc']) for r in rows]
print(f"Initial SOC: avg={statistics.mean(initial_socs):.1f}%, min={min(initial_socs):.1f}%, max={max(initial_socs):.1f}%")
print(f"Final SOC: avg={statistics.mean(final_socs):.1f}%, min={min(final_socs):.1f}%, max={max(final_socs):.1f}%")

# Optimization reward by location and time
print("\n=== OPTIMIZATION REWARD: Location x Time Slot ===")
for loc in ['Urban', 'Highway', 'Suburban']:
    for slot in ['Off-Peak', 'Mid-Peak', 'Peak']:
        vals = [float(r['optimization_reward']) for r in rows if r['location_type']==loc and r['time_slot']==slot]
        if vals:
            print(f"{loc}/{slot}: avg={statistics.mean(vals):.2f}")

# Hourly pattern from timestamp
print("\n=== HOURLY PATTERNS ===")
hour_wait = defaultdict(list)
for r in rows:
    # Parse timestamp like "1/1/2025 0:00"
    ts = r['timestamp']
    hour = int(ts.split(' ')[1].split(':')[0])
    hour_wait[hour].append(float(r['waiting_time']))

for h in range(24):
    if h in hour_wait:
        print(f"Hour {h:02d}: avg_wait={statistics.mean(hour_wait[h]):.2f}, count={len(hour_wait[h])}")

